        "lifestyle": [],                        // The patient's lifestyle habits, such as 'smoker', 'drinks alcohol', etc.
        "advice": "string",                     // Any advice or suggestions given to the patient
        "medical_history": [],                  // Any past chronic conditions or surgeries undergone by the patient
        "family_medical_history": []            // Any medical conditions or diseases in the patient's family, e.g., diabetes, hypertension, etc.
    }
}```

